function recentOrderCounts(customers, orders, sinceTs){
  // LEFT JOIN customers to orders, then keep recent ones, then group.
  const rows = [];
  for (const c of customers){
    const matches = orders.filter(o => o.customer_id === c.id);
    if (matches.length === 0){
      rows.push({ customer: c.id, order: null });
    } else {
      for (const o of matches) rows.push({ customer: c.id, order: o });
    }
  }
  // recency filter applied AFTER the join
  const filtered = rows.filter(r => r.order && r.order.ts >= sinceTs);
  // group the surviving rows into per-customer counts
  const counts = new Map();
  for (const r of filtered) counts.set(r.customer, (counts.get(r.customer) || 0) + 1);
  return [...counts.entries()].map(([customer,n]) => ({customer, n})).sort((a,b)=>a.customer<b.customer?-1:1);
}
this.recentOrderCounts = recentOrderCounts;

